// THE SCRIPTORIUM'S WORD-HOARD. Latin names, numerals, marginal notes and the voices of the scribes.
// Everything the Illuminated Codex says that is not generated by scripture.js lives here.

// Roman numerals in the manuscript manner: lowercase, and a final i written as j (iij, xvij).
export function roman(n, { upper = false, scribal = true } = {}) {
  n = Math.floor(Number(n))
  if (!(n > 0)) return upper ? 'N' : 'n' // nulla
  if (n >= 4000) {
    // Beyond four thousand the Romans drew a bar over the thousands (the vinculum).
    const over = [...roman(Math.floor(n / 1000), { upper, scribal: false })].map((c) => c + '̅').join('')
    const rest = n % 1000
    return rest ? over + roman(rest, { upper, scribal }) : over
  }
  const table = [[1000, 'm'], [900, 'cm'], [500, 'd'], [400, 'cd'], [100, 'c'], [90, 'xc'], [50, 'l'], [40, 'xl'], [10, 'x'], [9, 'ix'], [5, 'v'], [4, 'iv'], [1, 'i']]
  let out = ''
  for (const [v, s] of table) while (n >= v) { out += s; n -= v }
  if (scribal && out.endsWith('i') && out.length > 1) out = out.slice(0, -1) + 'j'
  return upper ? out.toUpperCase().replace(/J$/, 'I') : out
}

