// Mathematical Fraktur, for display only (always paired with real text for readers of screens).
const FRAKTUR_UPPER_EXCEPTIONS = { C: 0x212d, H: 0x210c, I: 0x2111, R: 0x211c, Z: 0x2128 }
export function fraktur(text) {
  return [...String(text)].map((c) => {
    if (c >= 'A' && c <= 'Z') return String.fromCodePoint(FRAKTUR_UPPER_EXCEPTIONS[c] ?? 0x1d504 + c.charCodeAt(0) - 65)
    if (c >= 'a' && c <= 'z') return String.fromCodePoint(0x1d51e + c.charCodeAt(0) - 97)
    return c
  }).join('')
}

